            background-position: center;
            height: 500px;
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            color: var(--white);
        }
        .hero h1 {
            font-size: 48px;
            margin-bottom: 20px;
            text-shadow: 0 2px 4px rgba(0,0,0,0.5);
        }
        .hero p {
            font-size: 20px;
            margin-bottom: 30px;
        }
        .section {
            padding: 80px 0;
        }
        .section-title {
            text-align: center;
            font-size: 32px;
            margin-bottom: 50px;
            color: var(--primary);
            position: relative;
        }
        .section-title::after {
            content: "";
            display: block;
            width: 60px;
            height: 3px;
            background-color: var(--secondary);
            margin: 15px auto 0;
        }
        .features {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 30px;
        }
        .feature-card {
            background: var(--white);
            padding: 30px;
            border-radius: 8px;
            text-align: center;
            box-shadow: 0 4px 6px rgba(0,0,0,0.05);
        }
        .feature-icon {
            font-size: 40px;
            margin-bottom: 20px;
            color: var(--secondary);
        }
        .feature-card h3 {
            margin-bottom: 15px;
            color: var(--primary);
        }
        .info-banner {
            background-color: var(--secondary);
            color: var(--white);
            padding: 40px 0;
            text-align: center;
        }
        .info-banner p {
            font-size: 18px;
            margin-top: 10px;
        }
        footer {
            background-color: var(--primary);
            color: var(--white);
            padding: 40px 0;
            text-align: center;
        }
        footer p {
            margin-bottom: 10px;
        }
        @media (max-width: 768px) {
            .navbar {
                flex-direction: column;
                height: auto;
                padding: 15px 0;
            }
            .nav-links {
                margin-top: 15px;
                gap: 15px;
                flex-wrap: wrap;
                justify-content: center;
            }
